68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    private final OwnerFieldsValidator ownerFieldsValidator;
83	
84	    private final HouseholdDuplicateValidator householdDuplicateValidator;
85	
86	    private final IdentityDuplicateValidator identityDuplicateValidator;
87	
88	    private final HouseholdIdGenerator householdIdGenerator;
89	
90	    private final TelephoneNormalizer telephoneNormalizer;
91	
92	    private final EmailNormalizer emailNormalizer;
93	
94	    private final AddressNormalizer addressNormalizer;
95	
96	    private final CustomerCodeGenerator customerCodeGenerator;
97	
98	    private final NamesakeCounter namesakeCounter;
99	
100	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
101	
102	    private final OwnerAuditLogger ownerAuditLogger;
103	
104	    public OwnerRestControllerV1(ClinicService clinicService,
105	                                 OwnerMapper ownerMapper,
106	                                 PetMapper petMapper,
107	                                 VisitMapper visitMapper,
108	                                 OwnerFieldsValidator ownerFieldsValidator,
109	                                 HouseholdDuplicateValidator householdDuplicateValidator,
110	                                 IdentityDuplicateValidator identityDuplicateValidator,
111	                                 HouseholdIdGenerator householdIdGenerator,
112	                                 TelephoneNormalizer telephoneNormalizer,
113	                                 EmailNormalizer emailNormalizer,
114	                                 AddressNormalizer addressNormalizer,
115	                                 CustomerCodeGenerator customerCodeGenerator,
116	                                 NamesakeCounter namesakeCounter,
117	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
118	                                 OwnerAuditLogger ownerAuditLogger) {
119	        this.clinicService = clinicService;
120	        this.ownerMapper = ownerMapper;
121	        this.petMapper = petMapper;
122	        this.visitMapper = visitMapper;
123	        this.ownerFieldsValidator = ownerFieldsValidator;
124	        this.householdDuplicateValidator = householdDuplicateValidator;
125	        this.identityDuplicateValidator = identityDuplicateValidator;
126	        this.householdIdGenerator = householdIdGenerator;
127	        this.telephoneNormalizer = telephoneNormalizer;
128	        this.emailNormalizer = emailNormalizer;
129	        this.addressNormalizer = addressNormalizer;
130	        this.customerCodeGenerator = customerCodeGenerator;
131	        this.namesakeCounter = namesakeCounter;
132	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
133	        this.ownerAuditLogger = ownerAuditLogger;
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
139	        Collection<Owner> owners;
140	        if (lastName != null) {
141	            owners = this.clinicService.findOwnerByLastName(lastName);
142	        } else {
143	            owners = this.clinicService.findAllOwners();
144	        }
145	        if (owners.isEmpty()) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
164	        if (ownerFieldsDto != null) {
165	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
166	        }
167	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
168	        if (!missingFields.isEmpty()) {
169	            throw new MissingOwnerFieldsException(missingFields);
170	        }
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        Collection<Owner> sameLastName =
174	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
175	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
176	        List<Owner> householdMembers = assignHousehold(owner, ownerFieldsDto, sameLastName);
177	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
178	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
179	        rejectIfDuplicateIdentity(owner);
180	        joinHousehold(owner, householdMembers);
181	        if (owner.getRegistrationDate() == null) {
182	            owner.setRegistrationDate(LocalDate.now());
183	        }
184	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
185	        LocalDate registrationDate = owner.getRegistrationDate();
186	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
187	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
188	            throw new DailyOwnerLimitException(registrationDate);
189	        }
190	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
191	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
192	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
193	            throw new CityOwnerLimitException(owner.getCity());
194	        }
195	        owner.setCustomerCode(customerCodeGenerator.generate(
196	            owner.getCity(), owner.getLastName(), cityOwnerCount));
197	        this.clinicService.saveOwner(owner);
198	        ownerAuditLogger.ownerCreated(owner);
199	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
200	        headers.setLocation(UriComponentsBuilder.newInstance()
201	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
202	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
203	    }
