51	 * <p>
52	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
53	 *
54	 * @author Vitaliy Fedoriv
55	 * @author Alexander Dudkin
56	 */
57	@ControllerAdvice
58	public class ExceptionControllerAdvice {
59	
60	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
61	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
62	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
63	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
64	
65	    private final OwnerFieldsValidator ownerFieldsValidator;
66	
67	    public ExceptionControllerAdvice(OwnerFieldsValidator ownerFieldsValidator) {
68	        this.ownerFieldsValidator = ownerFieldsValidator;
69	    }
70	
71	    /**
72	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
73	     * class.
74	     *
75	     * @param e     Object referring to the thrown exception.
76	     * @param status HTTP response status.
77	     * @param url URL request.
78	     */
79	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
80	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
81	        problemDetail.setType(URI.create(url.toString()));
82	        problemDetail.setTitle(e.getClass().getSimpleName());
83	        problemDetail.setDetail(detail);
84	        problemDetail.setProperty("timestamp", Instant.now());
85	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
86	        return problemDetail;
87	    }
88	
89	    /**
90	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
91	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
92	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
93	     * would catch it and report an authorization failure as a 500.
94	     *
95	     * @param e The {@link AccessDeniedException} to propagate
96	     * @throws AccessDeniedException always
97	     */
98	    @ExceptionHandler(AccessDeniedException.class)
99	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
100	        throw e;
101	    }
102	
103	    /**
104	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
105	     *
106	     * @param e The {@link Exception} to be handled
107	     * @param request {@link HttpServletRequest} object referring to the current request.
108	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
109	     */
110	    @ExceptionHandler(Exception.class)
111	    @ResponseBody
112	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
113	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
114	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
115	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
116	        return ResponseEntity.status(status).body(detail);
117	    }
118	
119	    /**
120	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
121	     * method returns a 404 Not Found status if an entity does not exist.
122	     *
123	     * @param e The {@link DataIntegrityViolationException} to be handled
124	     * @param request {@link HttpServletRequest} object referring to the current request.
125	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
126	     */
127	    @ExceptionHandler(DataIntegrityViolationException.class)
128	    @ResponseBody
129	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
130	        logger.warn("Data integrity violation at {} {}: {}",
131	            request.getMethod(),
132	            request.getRequestURI(),
133	            e.getMessage());
134	        logger.debug("Data integrity violation stacktrace", e);
135	        HttpStatus status = HttpStatus.NOT_FOUND;
136	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
137	        return ResponseEntity.status(status).body(detail);
138	    }
139	
140	    /**
141	     * Handles exception thrown by Bean Validation on controller methods parameters
142	     *
143	     * @param e The {@link MethodArgumentNotValidException} to be handled
144	     * @param request {@link HttpServletRequest} object referring to the current request.
145	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
146	     */
147	    @ExceptionHandler(MethodArgumentNotValidException.class)
148	    @ResponseBody
149	    public ResponseEntity<?> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
150	        HttpStatus status = HttpStatus.BAD_REQUEST;
151	        BindingErrorsResponse errors = new BindingErrorsResponse();
152	        BindingResult bindingResult = e.getBindingResult();
153	        if (bindingResult.getTarget() instanceof OwnerFieldsDto ownerFields) {
154	            List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFields);
155	            if (!missingFields.isEmpty()) {
156	                return ResponseEntity.status(status).body(new ValidationErrorsResponse(missingFields));
157	            }
158	        }
159	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
160	        if (bindingResult.hasErrors()) {
161	            errors.addAllErrors(bindingResult);
162	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
163	                .map(fieldError -> {
164	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
165	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
166	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
167	                        fieldError.getField(),
168	                        defaultMessage,
169	                        rejectedValue);
170	                    return new ValidationMessageDto(message)
171	                        .putAdditionalProperty("field", fieldError.getField())
172	                        .putAdditionalProperty("rejectedValue", rejectedValue)
173	                        .putAdditionalProperty("defaultMessage", defaultMessage);
174	                })
175	                .toList();
176	            logger.debug("Validation error at {} {}: {}",
177	                request.getMethod(),
178	                request.getRequestURI(),
179	                bindingResult.getFieldErrors());
180	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
181	            return ResponseEntity.status(status).body(detail);
